// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DNSResolver
 * @notice On-chain DNS resolution with graceful shutdown and temporary record staging
 * @dev Uses a two-phase commit for DNS record updates with shutdown capability
 */
contract DNSResolver is Ownable {
    enum State { ACTIVE, DRAINING, SHUTDOWN }

    struct DNSRecord {
        address resolver;
        uint64 ttl;
        uint64 timestamp;
        bytes32 contentHash;
    }

    struct StagedRecord {
        DNSRecord record;
        uint256 commitBlock;
        bool finalized;
        address stager;
    }

    State public currentState;
    uint256 public drainStartBlock;
    uint256 public constant DRAIN_PERIOD = 100;
    uint256 public constant COMMIT_DELAY = 5;

    mapping(bytes32 => DNSRecord) public records;
    mapping(bytes32 => StagedRecord) public stagedRecords;
    mapping(address => bool) public authorizedResolvers;

    // Temporary staging area - uses unpredictable slot derivation
    mapping(uint256 => bytes32) private tempSlots;
    mapping(uint256 => address) private tempSlotOwners;
    uint256 private tempNonce;

    event RecordStaged(bytes32 indexed domain, uint256 tempId);
    event RecordCommitted(bytes32 indexed domain);
    event ShutdownInitiated(uint256 drainStart);
    event ShutdownComplete();

    modifier whenActive() {
        require(currentState == State.ACTIVE, "Not active");
        _;
    }

    modifier whenNotShutdown() {
        require(currentState != State.SHUTDOWN, "Shutdown");
        _;
    }

    constructor() Ownable() {
        currentState = State.ACTIVE;
        tempNonce = 0;
    }

    function addResolver(address resolver) external onlyOwner {
        authorizedResolvers[resolver] = true;
    }

    function removeResolver(address resolver) external onlyOwner {
        authorizedResolvers[resolver] = false;
    }

    /**
     * @notice Stage a DNS record update in temporary storage
     * @dev The temp ID is derived from block-level entropy for uniqueness
     */
    function stageRecord(
        bytes32 domain,
        address resolver,
        uint64 ttl,
        bytes32 contentHash
    ) external whenActive returns (uint256 tempId) {
        require(authorizedResolvers[msg.sender], "Unauthorized");
        require(ttl > 0 && ttl <= 86400, "Invalid TTL");

        // Generate temporary slot ID with block hash for unpredictability
        tempId = _generateTempId(domain, msg.sender);

        StagedRecord storage staged = stagedRecords[domain];
        staged.record = DNSRecord({
            resolver: resolver,
            ttl: ttl,
            timestamp: uint64(block.timestamp),
            contentHash: contentHash
        });
        staged.commitBlock = block.number;
        staged.finalized = false;
        staged.stager = msg.sender;

        // Store reference in temp slot for cross-referencing
        tempSlots[tempId] = domain;
        tempSlotOwners[tempId] = msg.sender;

        emit RecordStaged(domain, tempId);
    }

    /**
     * @notice Commit a staged record after delay period
     */
    function commitRecord(bytes32 domain) external whenNotShutdown {
        StagedRecord storage staged = stagedRecords[domain];
        require(!staged.finalized, "Already finalized");
        require(staged.record.resolver != address(0), "No staged record");
        require(
            block.number >= staged.commitBlock + COMMIT_DELAY,
            "Commit delay not met"
        );

        records[domain] = staged.record;
        staged.finalized = true;

        emit RecordCommitted(domain);
    }

    /**
     * @notice Resolve a domain to its record
     */
    function resolve(bytes32 domain) external view returns (
        address resolver,
        uint64 ttl,
        uint64 timestamp,
        bytes32 contentHash
    ) {
        DNSRecord storage rec = records[domain];
        require(rec.resolver != address(0), "Domain not found");
        return (rec.resolver, rec.ttl, rec.timestamp, rec.contentHash);
    }

    /**
     * @notice Initiate graceful shutdown
     */
    function initiateShutdown() external onlyOwner whenActive {
        currentState = State.DRAINING;
        drainStartBlock = block.number;
        emit ShutdownInitiated(drainStartBlock);
    }

    /**
     * @notice Complete shutdown after drain period
     */
    function completeShutdown() external onlyOwner {
        require(currentState == State.DRAINING, "Not draining");
        require(
            block.number >= drainStartBlock + DRAIN_PERIOD,
            "Drain period not complete"
        );
        currentState = State.SHUTDOWN;
        emit ShutdownComplete();
    }

    /**
     * @notice Emergency: allow committing during drain if record was staged before drain
     */
    function emergencyCommit(bytes32 domain, uint256 tempId) external {
        require(currentState == State.DRAINING, "Not in drain state");
        require(tempSlots[tempId] == domain, "Temp ID mismatch");
        require(tempSlotOwners[tempId] == msg.sender, "Not temp slot owner");

        StagedRecord storage staged = stagedRecords[domain];
        require(!staged.finalized, "Already finalized");
        require(staged.record.resolver != address(0), "No staged record");
        require(staged.stager == msg.sender, "Not original stager");

        // During drain, still enforce commit delay for security
        require(
            block.number >= staged.commitBlock + COMMIT_DELAY,
            "Commit delay not met"
        );

        records[domain] = staged.record;
        staged.finalized = true;

        // Clean up temp slot
        delete tempSlots[tempId];
        delete tempSlotOwners[tempId];

        emit RecordCommitted(domain);
    }

    /**
     * @dev Generate a temporary ID for staging area
     * Uses blockhash for unpredictability in addition to sender/domain
     */
    function _generateTempId(
        bytes32 domain,
        address sender
    ) internal returns (uint256) {
        // Includes blockhash for unpredictability
        uint256 id = uint256(keccak256(abi.encodePacked(
            domain,
            sender,
            tempNonce,
            blockhash(block.number - 1)
        )));
        tempNonce++;
        return id;
    }

    function getTempNonce() external view returns (uint256) {
        return tempNonce;
    }
}
